//! Tier B/C golden fixtures (`tests/golden/tick/*`, `tests/golden/entity/*`,
//! `tests/golden/light/*`)
//! run through `mc_golden::tick_driver::drive` and compared with the Java
//! oracle's `expected.jsonl` (PLAN_v4 §4, tests/golden/README.md "Tier B/C/S").
//!
//! One test per fixture directory, generated by [`fixtures!`] together with
//! the list [`COVERED`] that [`every_tick_and_entity_fixture_has_a_test`]
//! checks against the directories on disk, so a new fixture cannot be
//! forgotten. A fixture that needs Java code the port does not have yet is
//! `#[ignore]`d with the missing class/method and the first observed
//! difference; `cargo test -- --ignored` shows the current state of each.
//! The Rust trace of every run is in `target/golden/<area>/<name>/actual.jsonl`.

use mc_golden::tick_driver::drive;
use mc_golden::{GoldenError, Scenario, ScenarioKind, compare, fixture_dir, parse_jsonl};

fn check(area: &str, name: &str) {
    if let Err(e) = mc_golden::run(fixture_dir(area, name), drive) {
        panic!("{area}/{name}: {e}");
    }
}

macro_rules! fixtures {
    ($( $(#[$attr:meta])* $test:ident => $area:literal / $name:literal; )*) => {
        $(
            #[test]
            $(#[$attr])*
            fn $test() {
                check($area, $name);
            }
        )*
        /// Every `(area, name)` that has a test function above.
        const COVERED: &[(&str, &str)] = &[$(($area, $name)),*];
    };
}

fixtures! {
    // Every "world": "generated" fixture stops before its first line (the
    // implicit `preload` line): tick_driver returns "worldgen not transcribed".
    // What it needs after worldgen is listed for planning, from its ops.

    // ---- tests/golden/entity -----------------------------------------------------
    #[ignore = "worldgen: ChunkProviderGenerate (WP-1.4), first diff line 1 (no trace); then EntityArrow(World) + EntityArrow.onUpdate"]
    entity_arrow_flight => "entity" / "arrow-flight";
    entity_flat_item_drop => "entity" / "flat-item-drop";
    #[ignore = "EntityPig(World) constructor not transcribed: first diff line 7 (t=0 op spawn kind Pig); then EntityLiving.onLivingUpdate / EntityCreature.updatePlayerActionState wander AI (WP-2.2)"]
    entity_flat_pig_falls => "entity" / "flat-pig-falls";
    #[ignore = "worldgen: ChunkProviderGenerate (WP-1.4), first diff line 1 (no trace); then lands on generated grass"]
    entity_item_drop => "entity" / "item-drop";
    #[ignore = "worldgen: ChunkProviderGenerate (WP-1.4), first diff line 1 (no trace); then HarnessPlayer/EntityPlayerSP (WP-2.5), EntityPig, EntityPlayer.attackTargetEntityWithCurrentItem, EntityLiving.attackEntityFrom"]
    entity_pig_attacked => "entity" / "pig-attacked";
    #[ignore = "worldgen: ChunkProviderGenerate (WP-1.4), first diff line 1 (no trace); then EntityPig and water physics, generated sand (BlockSand/EntityFallingSand)"]
    entity_pig_falls => "entity" / "pig-falls";

    // ---- tests/golden/light (WP-1.3) -------------------------------------------------
    light_blocklight_glowstone => "light" / "blocklight-glowstone";
    light_chunk_border => "light" / "chunk-border";
    light_occlusion => "light" / "occlusion";
    light_skylight_column => "light" / "skylight-column";

    // ---- tests/golden/tick -------------------------------------------------------
    #[ignore = "worldgen: ChunkProviderGenerate (WP-1.4), first diff line 1 (no trace); then use_item: HarnessPlayer, PlayerController.sendPlaceBlock, ItemDye.onItemUse, BlockSapling.growTree"]
    tick_bonemeal_sapling => "tick" / "bonemeal-sapling";
    #[ignore = "worldgen: ChunkProviderGenerate (WP-1.4), first diff line 1 (no trace)"]
    tick_empty_world_20 => "tick" / "empty-world-20";
    #[ignore = "BlockFlowing.onBlockAdded/updateTick (fluids task of WP-1.6): first diff line 9 (t=4 scheduled_ticks count 0, expected 5). Lighting (WP-1.3) is in"]
    tick_flat_flowing_water => "tick" / "flat-flowing-water";
    tick_flat_sand_falls => "tick" / "flat-sand-falls";
    tick_flat_torch_light => "tick" / "flat-torch-light";
    tick_flat_water_flow => "tick" / "flat-water-flow";
    #[ignore = "worldgen: ChunkProviderGenerate (WP-1.4), first diff line 1 (no trace); then HarnessPlayer (WP-2.5), BlockSapling random ticks, SpawnerAnimals.performSpawning (WP-2.3)"]
    tick_sapling_with_player => "tick" / "sapling-with-player";
    #[ignore = "worldgen: ChunkProviderGenerate (WP-1.4), first diff line 1 (no trace); then BlockFlowing (fluids task of WP-1.6)"]
    tick_water_flow => "tick" / "water-flow";
}

/// Every `tests/golden/{tick,entity,light}/<name>` with a `scenario.json` has a test
/// function above (and every test names an existing fixture).
#[test]
fn every_tick_and_entity_fixture_has_a_test() {
    let mut on_disk: Vec<(String, String)> = mc_golden::all_fixture_dirs()
        .expect("list tests/golden")
        .into_iter()
        .filter_map(|dir| {
            let name = dir.file_name()?.to_str()?.to_string();
            let area = dir.parent()?.file_name()?.to_str()?.to_string();
            matches!(area.as_str(), "tick" | "entity" | "light").then_some((area, name))
        })
        .collect();
    on_disk.sort();
    let mut covered: Vec<(String, String)> = COVERED
        .iter()
        .map(|(a, n)| (a.to_string(), n.to_string()))
        .collect();
    covered.sort();
    assert!(
        !on_disk.is_empty(),
        "no tick/entity/light fixtures found under tests/golden"
    );
    assert_eq!(
        on_disk, covered,
        "tests/golden/{{tick,entity,light}} fixtures and the fixtures! list in tests/golden_tick.rs differ"
    );
}

/// PLAN_v4 §4.4 item 2 (Rust side): the same driver with the scenario seed's
/// lowest bit flipped must not reproduce `entity/flat-item-drop`, so the
/// passing fixture really depends on the seeding protocol. Compares in
/// memory (no `actual.jsonl`, so it cannot race the real fixture test).
#[test]
fn flat_item_drop_with_perturbed_seed_fails() {
    let dir = fixture_dir("entity", "flat-item-drop");
    let scenario = Scenario::load(&dir).expect("load scenario");
    let text = std::fs::read_to_string(dir.join("expected.jsonl")).expect("read expected.jsonl");
    let expected = parse_jsonl(&text).expect("parse expected.jsonl");

    let trace = |s: &Scenario| {
        let mut w = mc_golden::TraceWriter::new();
        drive(s, &mut w).expect("drive");
        w
    };
    // Unperturbed: matches (the test is only meaningful if this holds).
    assert!(compare(&expected, trace(&scenario).lines()).is_ok());

    let mut perturbed = scenario.clone();
    match &mut perturbed.kind {
        ScenarioKind::Tick(t) => t.seed ^= 1,
        other => panic!("flat-item-drop is not a tick scenario: {other:?}"),
    }
    let mismatch = compare(&expected, trace(&perturbed).lines())
        .expect_err("a one-bit seed change must change the trace");
    // The Math.random() stream (EntityItem's yaw and motion) diverges at the
    // first entity line.
    let first: GoldenError = GoldenError::Mismatch {
        mismatch,
        expected: dir.join("expected.jsonl"),
        actual: "<in memory>".into(),
    };
    eprintln!("perturbed seed, first difference as expected:\n{first}");
}
